def longestRunAfterEach(nums):
    length = {}
    best = 0
    out = []
    for x in nums:
        if x not in length:
            left = length.get(x - 1, 0)
            right = length.get(x + 1, 0)
            total = left + right + 1
            length[x] = total
            length[x - left] = total
            length[x + right] = total
            if total > best:
                best = total
        out.append(best)
    return out
